function burdenRows(v){return Array.from({length:6},(_,i)=>({object:v['burden_object_'+(i+1)]??(i===0?v.burden||'':''),penalty:Math.max(0,Number(v['burden_penalty_'+(i+1)]??(i===0?v.burden_penalty:0))||0)}));}
