function highestProfession(values){return TIERS.slice().reverse().map(t=>String(values[`profession_${t}_name`]||'').trim()).find(Boolean)||'survivor';}
function talentGuide(){
 const groups=[['Ancestral Talents',[
 ['Underfoot / Deadly Aim / Warg-blooded','+1 Agility Bonus for each keyword.'],['Mountain Among Men / Inhuman Strength / Big Folk / Monstrous Body','+1 Brawn Bonus for each keyword.'],['Combat Prowess','+1 Combat Bonus.'],['Saber-toothed / Mighty Thews / Horrific Claws / Razor-sharp Claws','+5% Melee for each keyword.'],['Blue-blooded / Fieldwarden','+5% Ranged for each keyword.'],['Jack of All Trades','+5% to skills with no purchased ranks.'],['Servant of the Steward','+2 Peril Threshold unless Stressed, Frightened or Terrified.'],['Broad-bellied','+2 Peril Threshold unless starving.'],['Ironclad','+2 Peril Threshold while wearing armor.'],['Hide of Scales / Leathery Skin','+2 Damage Threshold each while unarmored.'],['Warg-blooded','+3 Damage Threshold when Seriously/Grievously Wounded or Dying.'],['Upper Crust / Bend Like a Reed','Use Fellowship Bonus for Damage Threshold if higher than Brawn Bonus.'],['Strength of the Mountain','Weapon and tool limits become 6 each.'],['Prehensile Tail','Forgives one excess weapon or tool.'],['Liquid Poise','Use higher of Agility/Perception Bonus for Initiative, and add +1.'],['Steam-powered','+1/+2/+3 Initiative at the −5/−10/−15 Peril stages.']]],['Professional Talents',[
 ['Spiritual Defense','+1 Damage Threshold per scar; blocked by Heavy armor.'],['The End Is Nigh','+3 Damage Threshold.'],['Fair Share','+2 weapon slots and +2 tool slots.']]],['General Talents',[
 ['Salt of the Earth','+3 Peril Threshold and +1 Damage Threshold.'],['Instincts','+1 Initiative.'],['Supernatural Paranoia','+3 Initiative while Stressed, Frightened or Terrified.']]]];
 return `<details class="card talent-rule-guide"><summary>Automatically Calculated Talents</summary><p class="info-label">Enter these keywords in talent names and mark Purchased to activate their effects. Descriptions are for your notes.</p><div class="talent-rule-table-scroll"><table class="talent-rule-table"><thead><tr><th scope="col">Talent Type</th><th scope="col">Talent / Keyword</th><th scope="col">Automatic Effect</th></tr></thead><tbody>${groups.map(([heading,entries])=>entries.map(([name,effect])=>`<tr><td>${esc(heading)}</td><th scope="row">${esc(name)}</th><td>${esc(effect)}</td></tr>`).join('')).join('')}</tbody></table></div></details>`;
}
function advancementLayout(){return SECTIONS.filter(s=>group(s)==='Advancement').map(s=>section(s)+(s.title==='Reward Points'?talentGuide():'')).join('');}
function magicRecords(kind,values=current.values){const config=magicConfig(kind),fields=SECTIONS.find(s=>s.title===config.title).fields;return Array.from({length:magicCount(values,kind)},(_,i)=>({index:i+1,fields:fields.slice(i*config.size,(i+1)*config.size)})).filter(record=>record.fields.some(f=>{const value=values[f.key];return value!==undefined&&value!==null&&String(value).trim()!==''&&String(value).trim()!=='None';}));}
