 return `<section class="sheet-panel"><h3>Profession Advancement</h3><table class="print-profession-table"><colgroup><col class="print-advance-label-col"><col><col><col></colgroup><thead><tr><th scope="col">Advancement</th>${TIERS.map((t,i)=>`<th scope="col"><span class="print-profession-title">${esc(String(v['profession_'+t+'_name']||'').trim()||'—')}</span> <span class="print-tier-cost">${(i+1)*10} RP</span></th>`).join('')}</tr></thead><tbody>${advances.map((advance,i)=>`<tr${[6,7,8,9,15].includes(i)?' class="print-advance-group"':''}><th scope="row">${advance.label}</th>${TIERS.map(t=>cell(advance,t)).join('')}</tr>`).join('')}</tbody><tfoot><tr><td colspan="4"><div class="print-rp-summary"><strong>Reward Points</strong><span>Total: ${Number(v.reward_points)||0}</span><span>Spent: ${ledger.spent}</span><span>Remaining: ${ledger.left}</span></div></td></tr></tfoot></table></section>`;
