 peril:{key:'peril_condition_track',title:'Peril Condition Track',fallback:'fine',rows:[['fine','Fine',''],['imperiled','Imperiled',''],['minus5','−5%','to Skill Tests'],['minus10','−10%','to Skill Tests'],['minus15','−15%','to Skill Tests'],['exhausted','Exhausted!','−20% to Skill Tests · Suffer an Affliction']]},
