function overview(){
 const v=current.values,c=calculate(v),value=k=>esc(v[k]||'—'),txt=k=>`<div class="sheet-text">${['malignancies','scars','injuries','personal_goals','reputation_text'].includes(k)?esc(String(v[k]??'').trim()):value(k)}</div>`,info=t=>`<div class="info-label">${esc(t)}</div>`;
 const panel=(title,body,kind='')=>`<article class="sheet-panel ${kind}"><h3>${esc(title)}${title==='Supplies'?`<span class="supply-header-max">MAX [IB]: ${c.supplyMax}</span>`:title==='Tools'||title==='Weapons'?`<span class="print-carry-limit">MAX: ${title==='Tools'?c.toolsLimit:c.weaponsLimit}</span>`:''}</h3>${body}${equipmentHint(({Tools:'tools','Small Objects':'objects',Supplies:'supplies',Weapons:'weapons'})[title])}</article>`;
 const rows=items=>`<table class="sheet-values"><tbody>${items.map(([label,val])=>`<tr><th scope="row">${esc(label)}</th><td>${esc(val)}</td></tr>`).join('')}</tbody></table>`;
 const parts=items=>`<details class="calculation-breakdown"><summary>Calculation breakdown</summary>${rows(items.map(p=>[p.label,p.value]))}</details>`;
 const squares=(count,max)=>`<span class="rank-marks" aria-label="${count} of ${max}">${Array.from({length:max},(_,i)=>`<span class="rank-mark ${i<count?'is-filled':''}" aria-hidden="true">${i<count?'■':'□'}</span>`).join('')}</span>`;
 const tracked=key=>{const f=SECTIONS.filter(s=>s.tracking).flatMap(s=>s.fields).find(f=>f.key===key);return f?field({...f,label:key==='initiative_temporary'?'Initiative Modifier':f.label.replace(/([a-z])([A-Z])/g,'$1 $2')}):'';};
 const identity=`<div class="sheet-story"><h2>My name is <strong>${value('name')}</strong> and I’m a <strong>${esc(highestProfession(v))}</strong></h2><p>I’m <strong>${[v.personal_age_group,v.personal_ancestry,v.personal_gender].filter(Boolean).map(esc).join(' ')||'—'}</strong>. I was born in <strong>${value('personal_season_of_birth')}</strong> in <strong>${value('personal_place_of_birth')}</strong>. I was raised in a/an <strong>${value('personal_upbringing')}</strong> home of the <strong>${value('personal_social_class')}</strong> class and became a follower of <strong>${value('personal_patron_deity')}</strong>.</p><p>I am of <strong>${value('personal_height')}</strong> stature and <strong>${value('personal_build')}</strong> build, with <strong>${value('personal_hair_color')}</strong> hair, <strong>${value('personal_eye_color')}</strong> eyes, <strong>${value('personal_complexion')}</strong> complexion and <strong>${value('personal_distinguishing_marks')}</strong>. My life changed the day that <strong>${esc(String(v.personal_death||'').trim()||'is shrouded in the fog of war')}</strong>. Yet I lived to tell the tale.</p><div class="story-line"><b>Inner Strength:</b> ${value('inner_strength')}</div><div class="story-line"><b>Tragic Flaw:</b> ${value('tragic_flaw')}</div></div>`;
 const history=panel(`Corruption`,`${corruptionSummary(v)}${txt('scars')}${info('Scars')}${txt('malignancies')}${info('Malignancies')}${txt('injuries')}${info('Injuries')}`);
 const goals=panel('My Goals & Ambitions',txt('personal_goals'),'sheet-goals'),reputation=panel('Renown',txt('reputation_text')+info('Current Reputation Points: '+(Number(v.reputation)||0)),'sheet-reputation');
 const bio=`${identity}${history}${panel('Languages I Speak',txt('personal_language'))}`;
 const portrait=portraitSource(v.portrait);
 const attributes=`<table class="sheet-attributes"><thead><tr><th>Primary Attribute</th><th>Bonus Advances</th></tr></thead><tbody>${['Agility','Brawn','Combat','Perception','Intelligence','Willpower','Fellowship'].map(a=>`<tr><td><strong>${a}</strong><span class="attribute-score">${c.attributes[a].score}%</span></td><td>${squares(c.attributes[a].advances,6)}<div><b>${a} Bonus: ${c.attributes[a].bonus}</b></div><details class="attribute-breakdown"><summary>Details</summary>${rows([...c.attributes[a].scoreParts,...c.attributes[a].bonusParts].map(p=>[p.label,p.value]))}</details></td></tr>`).join('')}</tbody></table>`;
 const skills=`<table class="sheet-skills"><thead><tr><th>Skills</th><th>Ranks</th><th>Success</th></tr></thead><tbody>${Object.entries(c.skills).map(([skill,s])=>`<tr><th scope="row">${skill}</th><td>${squares(s.rank,3)}</td><td><span title="${esc(s.parts.map(p=>p.label+': '+p.value).join(' + '))}">${s.total}%</span>${c.perilPenalty?`<small class="current-skill">${s.current}% with Peril</small>`:''}</td></tr>`).join('')}</tbody></table>`;
 const skillPanel=panel('Attributes and Skills',`<div class="attributes-skills-layout">${attributes}${skills}</div>${info('Success includes purchased ranks, recognized ancestral talents and talismans. Hover a success total for its breakdown. Peril-adjusted totals are listed separately.')}`,'sheet-skills-panel');
 const threshold=(type,title)=>{const stat=c[type];const applied=stat.parts.slice(1);return rows([['Base',stat.total],['Base +6',stat.total+6],['Base +12',stat.total+12],['Base +18',stat.total+18]])+`<div class="threshold-modifiers"><strong>Applied modifiers (included above)</strong>${applied.length?`<ul>${applied.map(p=>`<li><span>${esc(p.label)}</span><b>${p.value>0?'+':''}${p.value}</b></li>`).join('')}</ul>`:'<span>None</span>'}</div>`+parts(stat.parts);};
 const peril=panel('Peril Threshold',threshold('peril','Peril Threshold')+`<div class="overview-controls">${tracked('peril_condition_track')}${tracked('peril_stress')}${tracked('peril_situational')}<div class="starving-control">${tracked('starving')}</div><div class="other-conditions">${field({key:'other_conditions',label:'Conditions',type:'textarea'})}</div></div>`,'sheet-peril');
 const armor='<div class="sheet-armor-values">'+rows([['Armor',v.armor_name||'—'],['DTh Modifier / adjusted',`${Number(v.armor_dth)||0} / ${c.armor}`],['BB Requirement',Number(v.armor_bb)||0],['Qualities',v.armor_qualities||'—'],['Worn Clothes',v.armor_clothes||'—']])+ equipmentHint('armor')+'</div>';
 const damage=panel('Damage Threshold',threshold('damage','Damage Threshold')+`<div class="overview-controls">${tracked('damage_condition_track')}${tracked('damage_situational')}</div>`+(c.spiritualBlocked?info('Spiritual Defense is blocked by Heavy armor.'):'')+`<h4 class="sheet-subheading">Armor</h4>${armor}`,'sheet-damage');
 const weapons=panel('Weapons',`<div class="sheet-table-scroll"><table class="sheet-weapons"><thead><tr>${['','Weapon','Distance','Damage','Ammo (load)','Qualities'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${c.weapons.filter(w=>w.slot<=3||w.name||w.distance||w.damage||w.load||w.qualities||w.active).map(w=>`<tr><td><span class="weapon-equip-mark ${w.active?'is-filled':''}" aria-label="${w.active?'Equipped':'Not equipped'}">${w.active?'■':'□'}</span></td>${[w.name,w.distance,w.damage,w.load,w.qualities].map((x,i)=>`<td>${esc(x||'')}${i===2&&x&&c.stressPenalty?` <strong class="condition-penalty">${c.stressPenalty}</strong>`:''}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="6">No weapons entered.</td></tr>'}</tbody></table></div>`,'sheet-weapons-panel');
 const initiative=panel('Initiative',`<div class="initiative-value-row"><div class="initiative-final"><span>Final Initiative</span><output>${c.initiative.total}</output></div><div class="initiative-input">${tracked('initiative_temporary')}</div></div><details class="initiative-details"><summary>Calculation details</summary>${rows([['Base Initiative',c.initiative.base],['Burden',c.initiative.burden]])}<h4>Applied modifiers</h4>${c.initiative.parts.length>1?rows(c.initiative.parts.slice(1).map(p=>[p.label,p.value])):info('No additional modifiers.')}</details>`,'sheet-initiative');
 const sessionControls=`<div class="sheet-session-controls">${initiative}</div>`;
 const filled=key=>v[key]!==undefined&&v[key]!==null&&String(v[key]).trim()!=='';
 const toolKeys=Array.from({length:9},(_,i)=>'tool_'+(i+1)).filter((key,i)=>i<3||filled(key)),tools=panel('Tools',toolKeys.map(key=>`<div class="sheet-text">${esc(v[key]??'')}</div>`).join(''),'sheet-tools'),printTools=panel('Tools',Array.from({length:6},(_,i)=>`<div class="sheet-text">${esc(v['tool_'+(i+1)]??'')}</div>`).join(''),'sheet-tools');
 const objectKeys=['memento',...Array.from({length:9},(_,i)=>'object_'+(i+2))],objects=panel('Small Objects',`<div class="sheet-objects-list">${objectKeys.map(k=>`<div class="${k==='memento'?'sheet-memento':''}">${k==='memento'?'<b>Memento:</b>':Number(k.split('_')[1])+'.'} ${esc(v[k]??'')}</div>`).join('')}</div>`,'sheet-objects');
 const supplySlots=Array.from({length:6},(_,i)=>i+1),supplyTable=slots=>panel('Supplies',`<table class="sheet-values"><tbody>${slots.map(i=>`<tr><th scope="row">${esc(v['supply_name_'+i]||'')}</th><td>${esc(v['supply_rating_'+i]??'')}</td></tr>`).join('')}</tbody></table>`,'sheet-supplies'),supplies=supplyTable(supplySlots.filter(i=>filled('supply_name_'+i)||(filled('supply_rating_'+i)&&Number(v['supply_rating_'+i])!==0))),printSupplies=supplyTable(supplySlots);
 const titles='',burden=panel('Objects',burdenTable(),'sheet-burden').replace('Objects</h3>','Objects <span class="burden-heading-penalty">Penalty</span></h3>'),silver=panel('Silver Pieces',`<div class="sheet-silver-amount">${Number(v.silver)||0}</div>`+info('Each full 1,000 SP adds 1 burden.'),'sheet-silver');
 const talents=panel('Talents',Object.entries(c.talentEntries).map(([type,entries])=>`<h4 class="talent-heading">${type} Talents</h4>${entries.map(e=>`<div class="sheet-text"><b>${esc(e.name||'Unnamed talent')}</b> ${esc(e.description)}</div>`).join('')||'<div class="sheet-text">—</div>'}`).join('')+`<h4 class="talent-heading">Unique Bond</h4>${txt('talent_unique_bond')}`,'sheet-talents');
 const magicContent=magicReadOnly(),magic=magicContent?`<div class="sheet-magic">${magicContent}</div>`:'';
 const ledger=panel('Reward Points',rows([['Total Reward Points',Number(v.reward_points)||0],['Lifepath credit used',c.free],['RP spent',c.spent],['RP remaining',c.left]]),'sheet-ledger');
 overviewParts={bio,goals,reputation,portrait:portrait?`<div class="sheet-portrait"><img src="${esc(portrait)}" width="256" height="256" alt="Character token"></div>`:'',skills:skillPanel,peril,damage,weapons,initiative,tools,printTools,objects,supplies,printSupplies,titles,burden,silver,talents,magic,ledger};
 $('overview').innerHTML=`<div class="sheet-overview"><div class="sheet-hero"><div class="sheet-bio">${bio}</div><div class="sheet-character-side">${portrait?`<div class="sheet-portrait"><img src="${esc(portrait)}" width="256" height="256" alt="Character token"></div>`:''}${goals}${reputation}</div></div><div class="sheet-combat">${skillPanel}<div class="sheet-peril-stack">${peril}${sessionControls}</div>${damage}</div>${weapons}<div class="sheet-inventory">${tools}${objects}${silver}${supplies}${titles}${burden}</div>${talents}${magic}${ledger}</div>`;
}

function heading(){const portrait=$('character-portrait'),src=portraitSource(current.values.portrait);portrait.hidden=!src;if(src)portrait.src=src;else portrait.removeAttribute('src');$('character-name').textContent=current.values.name||'Unnamed survivor';$('subtitle').textContent=[current.values.personal_ancestry,...TIERS.slice().reverse().map(t=>current.values[`profession_${t}_name`]).filter(Boolean).slice(0,1)].filter(Boolean).join(' · ')||'Begin with a name. Build a life worth risking.';}
function characterCard(character){const v=character.values,portrait=portraitSource(v.portrait),selected=character.id===current.id,locked=character.locked===true,campaign=campaigns.find(c=>c.id===character.campaignId);
 return `<article class="gallery-card ${locked?'is-locked':''}" draggable="${!locked}" data-drag-character="${esc(character.id)}"><div class="gallery-portrait">${portrait?`<img src="${esc(portrait)}" width="256" height="256" alt="${esc(v.name||'Unnamed survivor')} portrait">`:'<span aria-hidden="true">⚔</span>'}</div><div class="gallery-card-body"><h4>${esc(v.name||'Unnamed survivor')}</h4><p class="gallery-profession">${esc(highestProfession(v))}</p><p class="muted">${esc([v.personal_ancestry,v.personal_gender].filter(Boolean).join(' ')||'Details not recorded')} <span class="gallery-inline-rp">${Number(v.reward_points)||0} RP</span></p>${selected?'<span class="gallery-current">Current character</span>':''}${locked?'<span class="gallery-lock-badge">Locked</span>':''}<label class="gallery-campaign-label">Campaign<select data-assign-character="${esc(character.id)}" ${locked?'disabled':''}><option value="">Unassigned</option>${campaigns.map(c=>`<option value="${esc(c.id)}" ${campaign?.id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="gallery-actions"><button type="button" data-gallery-action="open" data-character-id="${esc(character.id)}">Open character</button><button type="button" data-gallery-action="lock" data-character-id="${esc(character.id)}">${locked?'Unlock':'Lock'}</button><button type="button" class="gallery-remove" data-gallery-action="remove" data-character-id="${esc(character.id)}" ${locked?'disabled':''} aria-label="Remove ${esc(v.name||'Unnamed survivor')}">Remove</button></div></div></article>`;
}
function createLibraryBackup(){return JSON.parse(JSON.stringify({format:'zweihander-forge-backup',version:1,createdAt:new Date().toISOString(),activeCharacterId:current.id,characters,campaigns}));}
function planBackupRestore(backup,existingCharacters=characters,existingCampaigns=campaigns){
 if(!backup||backup.format!=='zweihander-forge-backup'||backup.version!==1||!Array.isArray(backup.characters)||!Array.isArray(backup.campaigns))throw Error('Choose a valid Character Forge full backup (version 1).');
 if(backup.characters.length>10000||backup.campaigns.length>10000)throw Error('This backup contains too many records.');
 const characterIds=new Set(),campaignIds=new Set();
 for(const c of backup.campaigns){if(!c||typeof c.id!=='string'||!c.id||typeof c.name!=='string'||!c.name.trim()||campaignIds.has(c.id))throw Error('Invalid or duplicate campaign in backup.');campaignIds.add(c.id);}
 for(const c of backup.characters){if(!c||typeof c.id!=='string'||!c.id||characterIds.has(c.id)||!c.values||typeof c.values!=='object'||Array.isArray(c.values))throw Error('Invalid or duplicate character in backup.');characterIds.add(c.id);if(Object.entries(c.values).some(([key,value])=>['__proto__','constructor','prototype'].includes(key)||(value!==null&&!['string','number','boolean'].includes(typeof value))))throw Error('Character fields must contain text, numbers or checkboxes.');if(c.campaignId!=null&&c.campaignId!==''&&!campaignIds.has(c.campaignId))throw Error('A character refers to a missing campaign.');}
 const nextCampaigns=existingCampaigns.map(c=>({...c})),usedIds=new Set([...existingCharacters.map(c=>c.id),...nextCampaigns.map(c=>c.id)]),mapping=new Map();let sequence=0;
 const freshId=()=>{let id;do{id=blank().id+'-restore-'+sequence++;}while(usedIds.has(id));usedIds.add(id);return id;};
 for(const c of backup.campaigns){const existing=nextCampaigns.find(p=>p.name.toLowerCase()===c.name.trim().toLowerCase());if(existing)mapping.set(c.id,existing.id);else{const next={id:freshId(),name:c.name.trim()};nextCampaigns.push(next);mapping.set(c.id,next.id);}}
 let activeCharacterId=null;const added=backup.characters.map(c=>{const id=freshId();if(c.id===backup.activeCharacterId)activeCharacterId=id;return {id,values:{...c.values},locked:c.locked===true,campaignId:c.campaignId?mapping.get(c.campaignId):null};});
 return {characters:[...existingCharacters,...added],campaigns:nextCampaigns,activeCharacterId,addedCharacters:added.length,addedCampaigns:nextCampaigns.length-existingCampaigns.length};
}
function exportLibraryBackup(){const blob=new Blob([JSON.stringify(createLibraryBackup(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Zweihander - Full Backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function restoreLibraryBackup(backup){const plan=planBackupRestore(backup);if(!window.confirm(`Add ${plan.addedCharacters} characters and ${plan.addedCampaigns} new campaigns from this backup? Existing characters will be kept. Portraits, campaign assignments and locks will be restored.`))return false;
 characters=plan.characters;campaigns=plan.campaigns;if(plan.activeCharacterId)current=characters.find(c=>c.id===plan.activeCharacterId);persist();tab='Gallery';render();if(storage)$('status').textContent=`Restored ${plan.addedCharacters} characters and ${plan.addedCampaigns} campaigns.`;return true;}

function galleryLayout(){return `<section class="character-gallery"><div class="gallery-heading"><div><h3>Character Gallery</h3><p class="muted">${characters.length} saved character${characters.length===1?'':'s'}</p></div><div class="gallery-backup-actions"><button type="button" data-gallery-action="new">New character</button><button type="button" data-gallery-action="backup-export">Export full backup</button><button type="button" data-gallery-action="backup-restore">Restore backup</button></div></div><p class="muted gallery-backup-hint">Full backups include every character, portrait image, campaign, assignment and lock state in one JSON file.</p><div class="gallery-grid">${characters.map(characterCard).join('')}</div></section>`;}
function addCampaign(name){const clean=String(name||'').trim().slice(0,100);if(!clean){$('status').textContent='Enter a campaign name.';return null;}if(campaigns.some(c=>c.name.toLowerCase()===clean.toLowerCase())){$('status').textContent='A campaign with that name already exists.';return null;}const campaign={id:blank().id,name:clean};campaigns.push(campaign);persist();return campaign;}
function assignCampaign(characterId,campaignId){const character=characters.find(c=>c.id===characterId);if(!character||character.locked||campaignId&&!campaigns.some(c=>c.id===campaignId))return false;character.campaignId=campaignId||null;persist();render();return true;}
function toggleCharacterLock(id){const character=characters.find(c=>c.id===id);if(!character)return;character.locked=!character.locked;persist();render();if(storage)$('status').textContent=character.locked?'Character locked: editing and deletion disabled.':'Character unlocked.';}
function campaignLayout(id){const selected=campaigns.find(c=>c.id===id);
 if(selected){const assigned=characters.filter(c=>c.campaignId===id),unassigned=characters.filter(c=>!campaigns.some(p=>p.id===c.campaignId));return `<section class="character-gallery"><div class="gallery-heading"><div><h3>${esc(selected.name)}</h3><p class="muted">${assigned.length} assigned character${assigned.length===1?'':'s'}</p></div></div><div class="campaign-dropzone" data-drop-campaign="${esc(id)}"><h4>Campaign Characters</h4><div class="gallery-grid">${assigned.map(characterCard).join('')||'<p class="muted">Assign a character below, or drop one here.</p>'}</div></div><div class="campaign-dropzone" data-drop-campaign=""><h4>Unassigned Characters</h4><div class="gallery-grid">${unassigned.map(characterCard).join('')||'<p class="muted">No unassigned characters.</p>'}</div></div></section>`;}
 return `<section class="character-gallery"><div class="gallery-heading"><div><h3>Campaigns</h3><p class="muted">Create a campaign, then assign characters using their dropdown or drag a card onto a campaign.</p></div></div><form id="create-campaign-form" class="campaign-create"><label for="campaign-name">Campaign name<input id="campaign-name" maxlength="100" required placeholder="Enter a campaign name"></label><button type="submit">Create campaign tab</button></form><div class="campaign-zones">${campaigns.map(c=>`<div class="campaign-dropzone" data-drop-campaign="${esc(c.id)}"><h4>${esc(c.name)}</h4><p>${characters.filter(p=>p.campaignId===c.id).length} characters</p><button type="button" data-open-campaign="${esc(c.id)}">Open campaign</button></div>`).join('')}<div class="campaign-dropzone" data-drop-campaign=""><h4>Unassigned</h4><p>Drop a character here to remove its campaign assignment.</p></div></div><div class="gallery-grid">${characters.map(characterCard).join('')}</div></section>`;
}

function removeCharacter(id){const character=characters.find(c=>c.id===id);if(!character)return false;if(character.locked){$('status').textContent='Unlock this character before removing it.';return false;}const name=character.values.name||'Unnamed survivor';if(!window.confirm(`Remove “${name}” and its saved character sheet from this device? This cannot be undone.`))return false;
 characters=characters.filter(c=>c.id!==id);if(!characters.length)characters=[blank()];if(current.id===id)current=characters[0];persist();render();if(storage)$('status').textContent=`Removed ${name}`;return true;}
function helpLayout(){const mechanics=[
['Attributes and bonuses','New characters start with base attributes of 30. Purchased primary adjustments add +5% before the tens digit is calculated. Secondary bonus advances, supported ancestral talents and custom bonuses are then added.'],
['Skills','Success uses the adjusted governing attribute, +10% per purchased rank (maximum three ranks), and supported talent and talisman bonuses. A Talisman of [Skill] adds +5 once per skill, including Thievery and Toughness. Peril penalties are shown separately.'],
['Peril and Horror','Peril stages apply 0, 0, −5, −10, −15 or −20 to skill tests. Horror applies −2 (Stressed), −4 (Frightened) or −6 (Terrified) to inflicted damage and peril. The penalty is displayed beside weapon damage; the entered damage formula stays unchanged. Horror also affects supported conditional talents.'],
['Thresholds','Peril Threshold starts at Willpower Bonus +3. Damage Threshold starts at Brawn Bonus, or Fellowship Bonus when a supported talent allows it and it is higher. Armor, equipped weapon qualities, supported talents and situational modifiers are included. Subsequent threshold steps add +6, +12 and +18. Starving disables Broad-bellied’s Peril benefit.'],
['Armor and weapons','Only equipped, non-Ruined weapons provide Hardened (+1 Peril Threshold) or Defensive (+1 Damage Threshold); each quality applies once. Ruined armor has 0 protection. Maker’s Mark adds +1; otherwise an unmet Brawn Bonus requirement can reduce armor protection, with a minimum of 1. Heavy armor blocks Spiritual Defense.'],
['Initiative and burden','Initiative starts at Perception Bonus +3; Liquid Poise can use Agility Bonus if higher. Supported talent bonuses, Ill-fitted armor (−3), excess weapons/tools, each full 1,000 silver pieces, extra burden and the entered Initiative Modifier are applied. Weapon/tool limits start at three each; Strength of the Mountain raises them to six and Fair Share adds two. Prehensile Tail forgives one excess item.'],
['Supplies','Maximum supply rating uses final Intelligence Bonus (IB), including all primary adjustments, bonus advancements, supported talents and custom bonuses.'],
['Corruption','Temporary and permanent corruption share the track. A combined total of 10 indicates Gain Malignancy. Permanent corruption reduces the remaining temporary allowance; the app does not automatically add a malignancy or reset corruption.'],
['Advancement and reward points','Purchased advances cost 10 RP in Basic, 20 RP in Intermediate and 30 RP in Advanced. The first nine purchased Basic advances are free. Each unique advance costs 10 RP. Remaining RP equals total RP minus spent RP. Only purchased advances and talents affect calculations.'],
['Talent recognition and manual entries','Supported talents are recognized by name keywords in purchased talent fields. The reference below lists those effects. Other talent text, spells, rituals and Other Conditions are recorded for reference and do not execute additional rules. Calculation details on the Overview show the modifiers applied to each value.']
];return `<section class="help-page"><h3>Help — Applied Mechanics</h3><p class="muted">These are the calculations implemented by Character Forge from the supplied sheet templates.</p>${mechanics.map(([title,text])=>`<article class="card help-card"><h4>${title}</h4><p>${text}</p></article>`).join('')}${talentGuide()}</section>`;}
function aboutLayout(){return `<section class="about-page"><div class="about-intro"><p class="eyebrow">ZWEIHÄNDER REFORGED</p><h3>Character Forge</h3><p>An offline workshop for your survivors, campaigns and character sheets.</p></div><article class="card about-card"><h4>License</h4><p>This app is licensed under the <strong>GNU General Public License v3.0 (GPL-3.0)</strong>.</p><p>You may use, modify and redistribute the software under the terms of that license. The software is provided without warranty.</p><a href="https://github.com/Verencius/Zweihander-Reforged-Sheet-App/blob/main/LICENSE" target="_blank" rel="noopener noreferrer">Read the full license</a><p class="muted">This is an independent character-sheet tool. The software license does not grant rights to the Zweihänder name, game books, or other third-party material.</p></article><article class="card about-card"><h4>Source Code</h4><p>Explore the source, download the standalone app, or report an issue on GitHub.</p><a href="https://github.com/Verencius/Zweihander-Reforged-Sheet-App" target="_blank" rel="noopener noreferrer">Verencius / Zweihander-Reforged-Sheet-App</a></article><article class="card about-card about-support"><h4>Support the Project</h4><p>If Character Forge helps at your table, you can support Verencius on Buy Me a Coffee.</p><a class="coffee-link" href="https://buymeacoffee.com/Verencius" target="_blank" rel="noopener noreferrer">Buy Verencius a coffee</a><p class="muted">Support is optional. The app remains free to use.</p></article></section>`;}
function render(){document.body?.classList?.toggle('overview-mode',tab==='Overview');document.body?.classList?.toggle('gallery-mode',tab==='Gallery'||tab==='Campaigns'||tab==='About'||tab==='Help'||tab.startsWith('campaign:'));library();heading();$('nav').innerHTML=tabs.map(t=>`${t==='Gallery'?'<div class="nav-divider" role="separator"></div>':''}${t==='Help'?'<div class="nav-divider" role="separator"></div>':''}<button data-tab="${esc(t)}" class="${tab===t?'active':''}" aria-current="${tab===t?'page':'false'}">${esc(t)}</button>${t==='Campaigns'&&campaigns.length?`<div class="campaign-nav-group">${campaigns.map(c=>`<button class="campaign-nav ${tab==='campaign:'+c.id?'active':''}" data-tab="campaign:${esc(c.id)}" aria-current="${tab==='campaign:'+c.id?'page':'false'}">${esc(c.name)}</button>`).join('')}</div>`:''}`).join('');$('lock-character').textContent=current.locked?'Unlock character':'Lock character';overview();$('overview').hidden=tab!=='Overview';$('editor').innerHTML=tab==='Help'?helpLayout():tab==='About'?aboutLayout():tab==='Gallery'?galleryLayout():tab==='Campaigns'?campaignLayout():tab.startsWith('campaign:')?campaignLayout(tab.slice(9)):tab==='Personal'?personalLayout():tab==='Equipment'?equipmentLayout():tab==='Advancement'?advancementLayout():SECTIONS.filter(s=>group(s)===tab).map(s=>section(s)).join('');}
$('nav').onclick=e=>{if(e.target.dataset.tab){tab=e.target.dataset.tab;render();}};
$('editor').addEventListener('click',e=>{const button=e.target.closest('[data-gallery-action]');if(!button)return;const action=button.dataset.galleryAction,id=button.dataset.characterId;if(action==='remove')removeCharacter(id);else if(action==='lock')toggleCharacterLock(id);else if(action==='open'){const character=characters.find(c=>c.id===id);if(character){current=character;tab='Overview';render();}}else if(action==='new')$('new').onclick();else if(action==='backup-export')exportLibraryBackup();else if(action==='backup-restore')$('backup-file').click();});
$('editor').addEventListener('input',e=>{const k=e.target.dataset.key;if(!k)return;if(current.locked)return;current.values[k]=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?(e.target.value===''?'':Number(e.target.value)):e.target.value;persist();heading();library();overview();updateAdvancement();updateCorruption();});
$('editor').addEventListener('click',e=>{const button=e.target.closest('[data-magic-action]');if(!button)return;const {magicAction:action,magicKind:kind,magicIndex:index}=button.dataset;if(!['spell','ritual'].includes(kind)||current.locked)return;changeMagic(current.values,kind,action,Number(index));persist();render();});
$('overview').addEventListener('change',e=>{const key=e.target.dataset.key;if(!key||current.locked)return;current.values[key]=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?(e.target.value===''?'':Number(e.target.value)):e.target.value;persist();overview();});
$('editor').addEventListener('change',async e=>{if(e.target.id!=='portrait-upload'||current.locked)return;const file=e.target.files[0];if(!file)return;const character=current;e.target.disabled=true;$('status').textContent='Preparing 256 × 256 token…';
 try{const portrait=await tokenImage(file);if(character.locked||!characters.includes(character))return;character.values.portrait=portrait;character.values.portrait_filename=file.name;persist();if(current===character)render();}catch(error){$('status').textContent='Image upload failed: '+error.message;}finally{e.target.disabled=false;e.target.value='';}
});
$('editor').addEventListener('click',e=>{if(e.target.id==='remove-portrait'&&!current.locked){delete current.values.portrait;delete current.values.portrait_filename;persist();render();}});
$('lock-character').onclick=()=>toggleCharacterLock(current.id);
$('editor').addEventListener('submit',e=>{if(e.target.id!=='create-campaign-form')return;e.preventDefault();const campaign=addCampaign($('campaign-name').value);if(campaign){tab='campaign:'+campaign.id;render();}});
$('editor').addEventListener('change',e=>{const id=e.target.dataset.assignCharacter;if(id)assignCampaign(id,e.target.value);});
$('editor').addEventListener('click',e=>{const button=e.target.closest('[data-open-campaign]');if(button){tab='campaign:'+button.dataset.openCampaign;render();}});
$('editor').addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag-character]');if(!card)return;const character=characters.find(c=>c.id===card.dataset.dragCharacter);if(!character||character.locked){e.preventDefault();return;}e.dataTransfer.setData('application/x-zweihander-character',character.id);e.dataTransfer.effectAllowed='move';});
$('editor').addEventListener('dragover',e=>{const zone=e.target.closest('[data-drop-campaign]');if(zone){e.preventDefault();e.dataTransfer.dropEffect='move';}});
$('editor').addEventListener('drop',e=>{const zone=e.target.closest('[data-drop-campaign]');if(!zone)return;e.preventDefault();const id=e.dataTransfer.getData('application/x-zweihander-character');if(id)assignCampaign(id,zone.dataset.dropCampaign);});
$('library').onchange=()=>{current=characters.find(c=>c.id===$('library').value);render();};
$('new').onclick=()=>{current=blank();characters.push(current);tab='Personal';persist();render();};
function exportName(values=current.values){const name=String(values.name||'').replace(/[<>:"/\\|?*\u0000-\u001f]/g,'').trim().replace(/[. ]+$/g,'');return 'Zweihander - '+(name||'Unnamed character');}
$('export').onclick=()=>{const b=new Blob([JSON.stringify({format:'zweihander-forge',version:1,values:current.values,locked:!!current.locked,campaign:campaigns.find(c=>c.id===current.campaignId)?.name||null},null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=exportName()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2e6)throw Error('Choose a JSON file smaller than 2 MB.');const parsed=JSON.parse(await f.text()),v=parsed.values??parsed.variables??parsed;if(!v||typeof v!=='object'||Array.isArray(v)||!Object.keys(v).some(k=>k==='name'||k.startsWith('attribute_')))throw Error('This file does not contain character fields.');if(Object.values(v).some(x=>!['string','number','boolean'].includes(typeof x)&&x!==null))throw Error('Character fields must contain text, numbers, or checkboxes.');current=blank();current.values={...current.values,...v};current.locked=parsed.locked===true;if(typeof parsed.campaign==='string'&&parsed.campaign.trim()){const existing=campaigns.find(c=>c.name.toLowerCase()===parsed.campaign.trim().toLowerCase()),campaign=existing||addCampaign(parsed.campaign);if(campaign)current.campaignId=campaign.id;}characters.push(current);persist();render();$('status').textContent='Character imported';}catch(err){$('status').textContent='Import failed: '+err.message;}e.target.value='';};
$('backup-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>50*1024*1024)throw Error('Choose a backup smaller than 50 MB.');restoreLibraryBackup(JSON.parse(await file.text()));}catch(error){$('status').textContent='Backup restore failed: '+error.message;}finally{e.target.value='';}};
let printing=false,originalDocumentTitle;function preparePrint(){if(printing){fitPrintPages();return;}originalDocumentTitle=document.title;document.title=exportName();overview();$('print-root').innerHTML=printMarkup();
 const root=$('print-root');root.querySelectorAll('.no-print,.field-hint,.calculation-breakdown,.attribute-breakdown').forEach(node=>node.remove());
 root.querySelectorAll('input,select,textarea').forEach(input=>{const output=document.createElement('span');output.className='print-field-value';output.textContent=input.tagName==='SELECT'?(input.options[input.selectedIndex]?.text||'—'):input.type==='checkbox'?(input.checked?'Yes':'No'):(input.value||'0');input.replaceWith(output);});
 // Duplicate editor IDs never enter the printed sheet.
 root.querySelectorAll('[id]').forEach(node=>{if(node.namespaceURI!=='http://www.w3.org/2000/svg')node.removeAttribute('id');});
 printing=true;document.body.classList.add('printing');fitPrintPages();}
window.addEventListener('beforeprint',preparePrint);window.addEventListener('afterprint',()=>{printing=false;if(originalDocumentTitle!==undefined){document.title=originalDocumentTitle;originalDocumentTitle=undefined;}document.body.classList.remove('printing');$('print-root').innerHTML='';});$('print').onclick=()=>{preparePrint();requestAnimationFrame(()=>{fitPrintPages();window.print();});};
render();if(!storage)$('status').textContent='Use Save JSON for a durable backup';else $('status').textContent='Autosave enabled · export JSON for a portable backup';
